makeArrow(new THREE.Vector3(15.5, 0.15, 0), new THREE.Vector3(17.7, 0.3, 0));

// === INSET PANEL ===
const panelGroup = new THREE.Group();
panelGroup.position.set(10, 5.2, 0);
scene.add(panelGroup);

// Panel background
