// Inset labels
addLabel('=', new THREE.Vector3(10 - 5.0, 5.2, 0.2), { fontSize: '14px', bold: true });
const insetLabelData = ['BN', 'ReLU', 'Conv 1×1', 'BN', 'ReLU', 'Conv 3×3', 'BN', 'ReLU', 'Conv 1×1'];
