// Helper: create a box with front/side coloring
function makeTensorBox(w, h, dep, color, x, y, z) {
  const geo = new THREE.BoxGeometry(w, h, dep);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y || h / 2, z || 0);
  scene.add(mesh);
  return mesh;
}

// Helper: create arrow line
function makeArrow(from, to, color = 0x333333) {
  const dir = new THREE.Vector3().subVectors(to, from);
  const len = dir.length();
  const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
  const mat = new THREE.LineBasicMaterial({ color });
  const line = new THREE.Line(geo, mat);
  scene.add(line);
  // arrowhead
  const coneGeo = new THREE.ConeGeometry(0.06, 0.15, 8);
  const coneMat = new THREE.MeshBasicMaterial({ color });
  const cone = new THREE.Mesh(coneGeo, coneMat);
  cone.position.copy(to);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  scene.add(cone);
  return { line, cone };
}

