  if (!residualActive) return;
  const now = performance.now();
  const dt = (now - _lastTime) / 1000;
  _lastTime = now;
  residualT += dt * 0.4; // speed
  if (residualT > 1.2) residualT = 0; // loop with pause

  const t = Math.min(residualT, 1);
  const mainPt = mainCurve.getPoint(t);
  pulseMain.position.copy(mainPt);
  const skipPt = skipPathCurve.getPoint(t);
  pulseSkip.position.copy(skipPt);

  // Flash ⊕ on arrival
  if (t > 0.95) {
    plusNode.material.color.setHex(0xff0000);
  } else {
    plusNode.material.color.setHex(0x111111);
  }
}

