  _patched = true;
  const _origLoop = animate;
  // We'll use a secondary RAF that runs alongside
  function _extraLoop() {
    _residualUpdate();
    requestAnimationFrame(_extraLoop);
  }
  _lastTime = performance.now();
  _extraLoop();
}
