  const dt = (now - _lastTime) / 1000;
  _lastTime = now;
  residualT += dt * 0.35;
  if (residualT > 1.3) residualT = 0;

  const t = Math.min(residualT, 1);
  const mainPt = mainCurve.getPoint(t);
  pulseMain.position.copy(mainPt);
  const skipPt = skipPathCurve.getPoint(t);
  pulseSkip.position.copy(skipPt);

  if (t > 0.95) {
